import { describe, test, expect } from "vitest";
import { readFileSync } from "node:fs";
import {
  decodeJointEnvelope, validateJointResearchPack, drawResearchEnvelope,
} from "../../packages/simulation/src/m7f-research-joint.js";

const packPath="tests/fixtures/m7f-joint-candidate.json";
// Optional external research artifact: generated by the real-data Python pipeline.
// Vectors and legality unit checks always run without the Cricsheet archive.
const vectorFixture=JSON.parse(readFileSync("tests/fixtures/m7f-joint-vectors.json","utf8"));

describe("M7F immutable offline joint sampler", () => {
  test("legal mask accepts only resolvable envelope combinations", () => {
    expect(decodeJointEnvelope("WIDE|1|0|STUMPED").teamRuns).toBe(1);
    expect(decodeJointEnvelope("NO_BALL|5|1|NONE").batBoundary).toBe(true);
    for (const invalid of ["WIDE|0|0|NONE", "NO_BALL|0|0|NONE",
      "NO_BALL|1|0|BOWLER", "WIDE|5|1|RUN_OUT", "LEGAL|1|1|NONE",
      "NO_BALL|4|1|NONE", "LEGAL|11|0|NONE"])
      expect(()=>decodeJointEnvelope(invalid)).toThrow();
  });
  test("research probabilities and version are independent of production game pack", () => {
    const mock = { version:"LC_T20_JOINT_ENVELOPE_RESEARCH_V1",gameplayIntegrationPermitted:true };
    expect(()=>validateJointResearchPack(mock)).toThrow();
  });
  test("model hash, categorical mass, and Python/TypeScript draws agree", () => {
    const pack=validateJointResearchPack(JSON.parse(readFileSync(packPath,"utf8")));
    expect(pack.candidateSha256).toBe(vectorFixture.packHash);
    for (const v of vectorFixture.vectors) {
      const decoded=drawResearchEnvelope(pack,v.phase,v.wickets,v.seed,v.ordinal);
      expect([decoded.legality,decoded.teamRuns,Number(decoded.batBoundary),decoded.wicketClass].join("|"))
        .toBe(v.expected);
    }
  });
  test("tampering with an integer quantum or research identifier is rejected", () => {
    const pack=JSON.parse(readFileSync(packPath,"utf8"));
    const key="POWERPLAY/0-2";
    const cat=pack.categories[0];
    pack.contextMass[key][cat]++;
    expect(()=>validateJointResearchPack(pack)).toThrow();
  });
  test("cannot sample once ten wickets have fallen or with invalid address", () => {
    const pack=validateJointResearchPack(JSON.parse(readFileSync(packPath,"utf8")));
    expect(()=>drawResearchEnvelope(pack,"POWERPLAY",10,"x",1)).toThrow();
    expect(()=>drawResearchEnvelope(pack,"MIDDLE",4,"",1)).toThrow();
  });
});
